// pubspec.yaml: local_auth: ^2.3.0
import 'package:local_auth/local_auth.dart';
import 'package:local_auth_android/local_auth_android.dart';
import 'package:local_auth_darwin/local_auth_darwin.dart';

final auth = LocalAuthentication();

Future<bool> authenticateUser({required String reason}) async {
  // 1. Support check
  final supported = await auth.isDeviceSupported();
  if (!supported) return false;
  final canBio = await auth.canCheckBiometrics;
  if (!canBio) {
    // Fallback: device passcode still works with biometricOnly: false
  }

  // 2. Determine available factors
  final available = await auth.getAvailableBiometrics();
  // available may contain: fingerprint, face, iris, strong, weak (Android 11+)

  try {
    return await auth.authenticate(
      localizedReason: reason,
      authMessages: const [
        AndroidAuthMessages(
          signInTitle: 'Verify identity',
          biometricHint: 'Touch the fingerprint sensor',
          cancelButton: 'Use PIN instead',
        ),
        IOSAuthMessages(cancelButton: 'Cancel', localizedFallbackTitle: 'Use passcode'),
      ],
      options: const AuthenticationOptions(
        biometricOnly: false,      // allow device passcode fallback
        stickyAuth: true,          // survive app backgrounding during prompt
        useErrorDialogs: true,     // system dialogs on 'no fingerprints enrolled' etc.
      ),
    );
  } on PlatformException catch (e) {
    // codes: NotAvailable / NotEnrolled / LockedOut / PermanentlyLockedOut / UserCancel / …
    return false;
  }
}

// ────── Usage pattern ──────
final ok = await authenticateUser(reason: 'Confirm to view your saved cards');
if (!ok) {
  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Auth cancelled')));
  return;
}
